const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { URL } = require('node:url');

const PORT = Number(process.env.PORT || 3000);
const ROOT = __dirname;
const DATA_FILE = path.join(ROOT, 'data', 'store.json');
const seed = JSON.parse(fs.readFileSync(path.join(ROOT, 'data', 'seed.json'), 'utf8'));
const CATEGORIES = ['Royalty & Payments','ISBN & Metadata Issues','Printing & Quality','Distribution & Availability','Book Status & Production Updates','General Inquiry'];
const STATUSES = ['Open','In Progress','Resolved','Closed'];
const PRIORITIES = ['Critical','High','Medium','Low'];
const KB = `BookLeaf Publishing operates in India and the US. Standard Free has no upfront cost; Bestseller Breakthrough is a premium package. BookLeaf handles cover design, typesetting, ISBN, printing, distribution and royalties. Royalty is 80% of net profit (MRP minus printing, platform commission and shipping), calculated quarterly and paid within 45 days of quarter end. Minimum payout is ₹1,000; smaller amounts roll over. Payments go to the linked bank account. Every BookLeaf title gets a unique ISBN under BookLeaf's imprint; own-imprint ISBNs must be obtained independently. ISBN errors are high priority and escalated to production within 48 hours. Quality defects: request photos; free reprint after verification, 5–7 business days. New listings usually take 7–10 business days; unavailable listings usually need stock sync, 24–48 hours. Production stages: Manuscript Received, Editing, Cover Design, Typesetting, Proofreading, ISBN Assignment, Printing, Distribution Setup, Published & Live. Metadata changes typically take 3–5 business days. Communicate with empathy, own BookLeaf errors, give specific timelines, and end with a clear next step. Do not invent account facts.`;
if (!fs.existsSync(DATA_FILE)) {
  const now = Date.now();
  const tickets = [
    {id:'TKT-1048',authorId:'AUTH003',bookId:'BK005',subject:'Royalty payout for my first sales',description:'I can see sales in my dashboard but have not received a payout yet. Could you explain when it will be paid?',category:'Royalty & Payments',priority:'High',status:'Open',createdAt:new Date(now-1000*60*60*30).toISOString(),assignedTo:null,notes:[],messages:[]},
    {id:'TKT-1047',authorId:'AUTH007',bookId:'BK013',subject:'Production timeline for Midnight in Mysore',description:'My book has been in cover design for a while. Can you share the next step and expected timeline?',category:'Book Status & Production Updates',priority:'Medium',status:'In Progress',createdAt:new Date(now-1000*60*60*54).toISOString(),assignedTo:'Maya Chen',notes:[{text:'Checking whether cover approval is pending.',at:new Date(now-1000*60*60*20).toISOString(),by:'Maya Chen'}],messages:[]},
    {id:'TKT-1046',authorId:'AUTH002',bookId:'BK004',subject:'Amazon listing is currently unavailable',description:'My book is showing as currently unavailable on Amazon India, though it was live last week.',category:'Distribution & Availability',priority:'High',status:'Open',createdAt:new Date(now-1000*60*60*8).toISOString(),assignedTo:null,notes:[],messages:[]},
    {id:'TKT-1045',authorId:'AUTH005',bookId:'BK009',subject:'Update my author bio',description:'I would like to make a small change to my author bio on the book listings.',category:'General Inquiry',priority:'Low',status:'Resolved',createdAt:new Date(now-1000*60*60*92).toISOString(),assignedTo:'Ravi Shah',notes:[],messages:[{text:'Thanks for reaching out. Please send the revised bio through your dashboard and our team will submit it to the listing platforms. Changes typically appear within 3–5 business days. Next step: reply here with the updated copy and we’ll take it from there.',at:new Date(now-1000*60*60*18).toISOString(),by:'Ravi Shah'}]}
  ];
  fs.writeFileSync(DATA_FILE, JSON.stringify({tickets}, null, 2));
}
let store = JSON.parse(fs.readFileSync(DATA_FILE,'utf8'));
const sessions = new Map();
const clients = new Map();
const persist = () => fs.writeFileSync(DATA_FILE, JSON.stringify(store,null,2));
const json = (res,status,data) => {res.writeHead(status,{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'});res.end(JSON.stringify(data));};
const fail = (res,status,code,message) => json(res,status,{error:{code,message}});
const parseBody = req => new Promise((resolve,reject)=>{let b='';req.on('data',c=>{b+=c;if(b.length>1e6)reject(new Error('Request body too large'));});req.on('end',()=>{try{resolve(b?JSON.parse(b):{});}catch{reject(new Error('Request body must be valid JSON'));}});});
const broadcast = (ticket) => {const payload=`event: ticket\ndata: ${JSON.stringify(ticket)}\n\n`;for(const [res,user] of clients)if(user.role==='admin'||user.id===ticket.authorId)res.write(payload);};
function classify(text) {const s=text.toLowerCase(); if(/isbn|metadata|wrong title|duplicate/.test(s))return CATEGORIES[1];if(/print|binding|blurry|misprint|quality|defect/.test(s))return CATEGORIES[2];if(/amazon|flipkart|unavailable|distribution|listing|stock/.test(s))return CATEGORIES[3];if(/production|typeset|cover|proof|status|timeline|stage/.test(s))return CATEGORIES[4];if(/royalt|payment|payout|paid|bank|sales|earning/.test(s))return CATEGORIES[0];return CATEGORIES[5];}
function prioritize(text, category) {const s=text.toLowerCase();if(/wrong isbn|duplicate isbn|misprint|defect|haven't received|six months|6 months|overdue|urgent|damaged/.test(s))return 'Critical';if(category==='Royalty & Payments'||category==='ISBN & Metadata Issues'||/unavailable/.test(s))return 'High';if(/update|bio|description|question|can i/.test(s))return 'Low';return 'Medium';}
function auth(req,res,role) {const token=(req.headers.authorization||'').replace(/^Bearer\s+/i,'')||new URL(req.url,'http://localhost').searchParams.get('token');const user=sessions.get(token);if(!user){fail(res,401,'UNAUTHORIZED','Please sign in to continue.');return null;}if(role&&user.role!==role&&user.role!=='admin'){fail(res,403,'FORBIDDEN','You do not have access to this resource.');return null;}return user;}
function publicTicket(t) {return {...t};}
async function aiDraft(ticket, author) {
 const book=author.books.find(b=>b.book_id===ticket.bookId);
 const context=`Author: ${author.name}. Book: ${book?`${book.title}; status ${book.status}; pending royalty ₹${book.royalty_pending}`:'General/account query'}. Category: ${ticket.category}. Query: ${ticket.description}`;
 if(process.env.OPENAI_API_KEY){try{const r=await fetch('https://api.openai.com/v1/chat/completions',{method:'POST',headers:{Authorization:`Bearer ${process.env.OPENAI_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({model:process.env.OPENAI_MODEL||'gpt-4o-mini',temperature:0.3,max_tokens:240,messages:[{role:'system',content:`You are a BookLeaf Publishing support representative. Draft a concise, empathetic reply using only the relevant policy context. Be specific, own errors when known, give a next step and timeline. If a fact is unknown, ask for it rather than inventing it.\nKnowledge base: ${KB}`},{role:'user',content:context}]})});if(!r.ok)throw new Error(`AI service returned ${r.status}`);const d=await r.json();return {draft:d.choices?.[0]?.message?.content?.trim()||'',source:'ai'};}catch(e){console.error('AI draft unavailable:',e.message);}}
 const category=ticket.category;
 if(category==='Royalty & Payments')return {draft:`Hi ${author.name.split(' ')[0]},\n\nI understand it’s frustrating to wait for royalty information. BookLeaf calculates royalties quarterly and issues payments within 45 days after the quarter ends. Amounts below ₹1,000 roll over to the next quarter, and payments are sent to the bank account linked in your dashboard.\n\nOur team will review the sales and payout details for ${book?.title||'your title'} and get back to you within 48 hours. Please confirm that your bank details are current in your dashboard so we can check this promptly.`,source:'fallback'};
 if(category==='Printing & Quality')return {draft:`Hi ${author.name.split(' ')[0]},\n\nI’m sorry the copy did not meet the quality you expected. Please reply with clear photos of the affected pages and the book’s order details. Once we verify the issue, we’ll arrange a free reprint; standard print turnaround is 5–7 business days.\n\nOur team will review your photos and confirm the next step within 48 hours.`,source:'fallback'};
 if(category==='Distribution & Availability')return {draft:`Hi ${author.name.split(' ')[0]},\n\nI understand the concern about your listing. An “unavailable” message is usually caused by a stock sync issue. We’ll ask our distribution team to trigger a re-sync; this typically takes 24–48 hours.\n\nWe’ll update you here once we confirm the listing is live again.`,source:'fallback'};
 if(category==='ISBN & Metadata Issues')return {draft:`Hi ${author.name.split(' ')[0]},\n\nThank you for flagging this. An ISBN mismatch needs prompt investigation, and I’m escalating it to our production team now. We’ll review the record and get back to you within 48 hours.\n\nIf you can, please attach a photo or link showing the ISBN you’re seeing so we can verify the mismatch.`,source:'fallback'};
 if(category==='Book Status & Production Updates')return {draft:`Hi ${author.name.split(' ')[0]},\n\nThanks for checking in. Your title is currently listed as “${book?.status||'in progress'}”. The next stage depends on completion of the current production step; our team will verify the latest update and share a specific timeline within 48 hours.\n\nWe’ll keep you posted here as your book moves forward.`,source:'fallback'};
 return {draft:`Hi ${author.name.split(' ')[0]},\n\nThanks for getting in touch. We’re reviewing your request and will follow up with the right next steps within 2 business days.\n\nIf there are any details or files that would help us look into this, please reply here and we’ll include them in our review.`,source:'fallback'};
}
async function handle(req,res){const u=new URL(req.url,'http://localhost');const p=u.pathname;
 if(req.method==='GET'&&p.startsWith('/api/')){if(p==='/api/health')return json(res,200,{status:'ok'});}
 if(req.method==='POST'&&p==='/api/auth/login'){let b;try{b=await parseBody(req)}catch(e){return fail(res,400,'INVALID_JSON',e.message)}const email=String(b.email||'').trim().toLowerCase();if(email==='admin@bookleaf.com'&&b.password==='admin123'){const token=crypto.randomBytes(24).toString('hex');const user={id:'ADMIN',name:'Maya Chen',email,role:'admin'};sessions.set(token,user);return json(res,200,{token,user});}const author=seed.authors.find(a=>a.email.toLowerCase()===email);if(!author||b.password!=='bookleaf123')return fail(res,401,'INVALID_CREDENTIALS','Email or password is incorrect.');const token=crypto.randomBytes(24).toString('hex');const user={id:author.author_id,name:author.name,email:author.email,role:'author'};sessions.set(token,user);return json(res,200,{token,user});}
 if(req.method==='POST'&&p==='/api/auth/logout'){const token=(req.headers.authorization||'').replace(/^Bearer\s+/i,'');sessions.delete(token);return json(res,200,{ok:true});}
 if(req.method==='GET'&&p==='/api/events'){const user=auth(req,res);if(!user)return;res.writeHead(200,{'Content-Type':'text/event-stream','Cache-Control':'no-cache','Connection':'keep-alive'});res.write('event: ready\ndata: {}\n\n');clients.set(res,user);req.on('close',()=>clients.delete(res));return;}
 if(p.startsWith('/api/')){const user=auth(req,res);if(!user)return;
  if(req.method==='GET'&&p==='/api/me')return json(res,200,{user});
  if(req.method==='GET'&&p==='/api/books'){if(user.role==='admin')return json(res,200,{authors:seed.authors});const author=seed.authors.find(a=>a.author_id===user.id);return json(res,200,{books:author.books});}
  if(req.method==='GET'&&p==='/api/tickets'){let list=store.tickets;if(user.role!=='admin')list=list.filter(t=>t.authorId===user.id);const status=u.searchParams.get('status'),category=u.searchParams.get('category'),priority=u.searchParams.get('priority');if(status)list=list.filter(t=>t.status===status);if(category)list=list.filter(t=>t.category===category);if(priority)list=list.filter(t=>t.priority===priority);list=[...list].sort((a,b)=>{const rank={Critical:0,High:1,Medium:2,Low:3};return rank[a.priority]-rank[b.priority]||new Date(a.createdAt)-new Date(b.createdAt)});return json(res,200,{tickets:list,authors:user.role==='admin'?seed.authors.map(a=>({id:a.author_id,name:a.name,email:a.email})):undefined});}
  if(req.method==='POST'&&p==='/api/tickets'){if(user.role!=='author')return fail(res,403,'FORBIDDEN','Only authors can create tickets.');let b;try{b=await parseBody(req)}catch(e){return fail(res,400,'INVALID_JSON',e.message)}const subject=String(b.subject||'').trim(),description=String(b.description||'').trim(),bookId=b.bookId||null;if(subject.length<4||subject.length>120)return fail(res,422,'VALIDATION_ERROR','Subject must be between 4 and 120 characters.');if(description.length<12||description.length>4000)return fail(res,422,'VALIDATION_ERROR','Description must be between 12 and 4,000 characters.');const a=seed.authors.find(x=>x.author_id===user.id);if(bookId&&!a.books.some(x=>x.book_id===bookId))return fail(res,422,'INVALID_BOOK','Choose one of your own books.');const category=classify(`${subject} ${description}`);const t={id:`TKT-${Math.floor(Date.now()/1000).toString().slice(-6)}`,authorId:user.id,bookId,subject,description,category,priority:prioritize(`${subject} ${description}`,category),status:'Open',createdAt:new Date().toISOString(),assignedTo:null,notes:[],messages:[]};store.tickets.push(t);persist();broadcast(t);return json(res,201,{ticket:t});}
  const ticketMatch=p.match(/^\/api\/tickets\/([^/]+)(?:\/(draft|messages|notes))?$/);if(ticketMatch){const [,id,action]=ticketMatch;const ticket=store.tickets.find(t=>t.id===id);if(!ticket)return fail(res,404,'NOT_FOUND','Ticket not found.');if(user.role!=='admin'&&ticket.authorId!==user.id)return fail(res,404,'NOT_FOUND','Ticket not found.');
   if(req.method==='GET'&&!action)return json(res,200,{ticket});
   if(req.method==='POST'&&action==='draft'){if(user.role!=='admin')return fail(res,403,'FORBIDDEN','Admin access required.');const author=seed.authors.find(a=>a.author_id===ticket.authorId);return json(res,200,await aiDraft(ticket,author));}
   if(req.method==='POST'&&action==='messages'){if(user.role!=='admin')return fail(res,403,'FORBIDDEN','Admin access required.');let b;try{b=await parseBody(req)}catch(e){return fail(res,400,'INVALID_JSON',e.message)}const text=String(b.text||'').trim();if(text.length<2||text.length>5000)return fail(res,422,'VALIDATION_ERROR','Response must be between 2 and 5,000 characters.');ticket.messages.push({text,at:new Date().toISOString(),by:user.name});ticket.status='Resolved';persist();broadcast(ticket);return json(res,201,{ticket});}
   if(req.method==='POST'&&action==='notes'){if(user.role!=='admin')return fail(res,403,'FORBIDDEN','Admin access required.');let b;try{b=await parseBody(req)}catch(e){return fail(res,400,'INVALID_JSON',e.message)}const text=String(b.text||'').trim();if(!text||text.length>2000)return fail(res,422,'VALIDATION_ERROR','Note must be between 1 and 2,000 characters.');ticket.notes.push({text,at:new Date().toISOString(),by:user.name});persist();return json(res,201,{ticket});}
   if(req.method==='PATCH'&&!action){if(user.role!=='admin')return fail(res,403,'FORBIDDEN','Admin access required.');let b;try{b=await parseBody(req)}catch(e){return fail(res,400,'INVALID_JSON',e.message)}if(b.status!==undefined){if(!STATUSES.includes(b.status))return fail(res,422,'INVALID_STATUS','Choose a valid ticket status.');ticket.status=b.status;}if(b.category!==undefined){if(!CATEGORIES.includes(b.category))return fail(res,422,'INVALID_CATEGORY','Choose a valid category.');ticket.category=b.category;}if(b.priority!==undefined){if(!PRIORITIES.includes(b.priority))return fail(res,422,'INVALID_PRIORITY','Choose a valid priority.');ticket.priority=b.priority;}if(b.assignedTo!==undefined)ticket.assignedTo=b.assignedTo;persist();broadcast(ticket);return json(res,200,{ticket});}
  }
  return fail(res,404,'NOT_FOUND','API route not found.');
 }
 const file=p==='/'?'/index.html':p;const full=path.normalize(path.join(ROOT,'public',file));if(!full.startsWith(path.join(ROOT,'public')))return fail(res,403,'FORBIDDEN','Invalid path.');fs.readFile(full,(e,data)=>{if(e)return fail(res,404,'NOT_FOUND','File not found.');const type={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8','.svg':'image/svg+xml'}[path.extname(full)]||'application/octet-stream';res.writeHead(200,{'Content-Type':type});res.end(data);});
}
http.createServer((req,res)=>{handle(req,res).catch(e=>{console.error(e);if(!res.headersSent)fail(res,500,'INTERNAL_ERROR','Something went wrong. Please try again.');else res.end();});}).listen(PORT,()=>console.log(`BookLeaf portal running at http://localhost:${PORT}`));
